def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    steps = [f'讀題定位：圈出「{tag}」與題目中的支點、力臂、繩段、距離或負載。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合簡單機械的力與距離取捨。', '排除誘答：分清改變方向、放大力、增加距離與能量守恆，不把省力誤解成製造能量。', '最後回查：確認答案有交代機械的結構條件與實驗證據範圍。']
    return {'id': f'question-science-content-eb-iv-7-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-eb-iv-7'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究槓桿、滑輪、斜面、機械利益與效率的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-eb-iv-7', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '簡單機械的功能', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先辨識機械的支點、力臂與受力方向，再判斷力與距離的取捨及效率。', 'solutionSteps': steps}

